
import { swalSuccess, swalError2 } from '~/common'
export default {
    props: {
        isCreate: {
            type: Boolean,
            require: true,
            default: true,
        },
        recordId: {
            type: Number,
            require: false,
            default: 0,
        }
    },
    data() {
        return {
            form: {
                "id": null,
                "mnemonic": "BNK",
                "name": "Dcommerce",
                "tel": "123-456-7890",
                "email": "info@abccorp.com",
                "address": "123 Main St",
                "province": "Ontario",
                "district": "Toronto",
                "village": "Downtown",
                "remark": "This is a sample company",
                "bank": "ທະນາຄານ BCEL",
                "accounts": "",
                "profile_image_path": null,
                isActive: true
            },
            items: ['Gold', 'Silver', 'Platinum', 'Diamond', 'Master'],
            isloading: false,
            // Image handling
            selectedFile: null,
            previewUrl: null,
            uploading: false,
            deleting: false,
            nameRules: [
                value => !!value || 'Name is required',
                value => (value && value.length <= 100) || 'Name must be less than 20 characters'
            ],
        };
    },
    computed: {
        currentImageUrl() {
            if (this.form.profile_image_path) {
                // Construct full URL for the image
                return `${this.$axios.defaults.baseURL || ''}/${this.form.profile_image_path}`
            }
            return null
        }
    },
    async created() {
        this.loadEntry();
    },
    methods: {
        async commitRecord() {
            if (this.$refs.form.validate() && !this.isloading) {
                this.isloading = true
                let api = this.isCreate ? 'api/company/create' : `api/company/update/${this.recordId}`
                console.log("API => ", api);
                
                try {
                    if (this.isCreate) {
                        await this.$axios.post(api, this.form)
                    } else {
                        await this.$axios.put(api, this.form)
                    }
                    
                    this.refreshData()
                    swalSuccess(this.$swal, 'Succeed', 'Your transaction completed');
                } catch (error) {
                    console.log("Error: ", error);
                    swalError2(this.$swal, "Error", 'ເກີດຂໍ້ຜິດພາດ ກະລຸນາລອງໃຫມ່ ພາຍຫລັງ');
                } finally {
                    this.isloading = false
                }
            }
        },

        async loadEntry() {
            console.log(`===> Update form record load`);
            if (this.recordId && !this.isCreate) {
                try {
                    const response = await this.$axios.get(`api/company/find/${this.recordId}`)
                    this.form = response.data
                } catch (error) {
                    console.log("Cannot fetch data " + error);
                }
            }
        },

        // Image handling methods
        onFileSelected(file) {
            if (file) {
                // Validate file type
                const allowedTypes = ['image/jpeg', 'image/jpg', 'image/png', 'image/gif']
                if (!allowedTypes.includes(file.type)) {
                    this.$toast.error('ກະລຸນາເລືອກໄຟລ໌ຮູບພາບ (JPG, PNG, GIF)')
                    this.clearSelectedFile()
                    return
                }

                // Validate file size (5MB max)
                const maxSize = 5 * 1024 * 1024 // 5MB
                if (file.size > maxSize) {
                    this.$toast.error('ຂະໜາດໄຟລ໌ໃຫຍ່ເກີນໄປ (ສູງສຸດ 5MB)')
                    this.clearSelectedFile()
                    return
                }

                // Create preview URL
                this.previewUrl = URL.createObjectURL(file)
            } else {
                this.clearSelectedFile()
            }
        },

        clearSelectedFile() {
            this.selectedFile = null
            if (this.previewUrl) {
                URL.revokeObjectURL(this.previewUrl)
                this.previewUrl = null
            }
            if (this.$refs.fileInput) {
                this.$refs.fileInput.reset()
            }
        },

        async uploadProfileImage() {
            if (!this.selectedFile) {
                this.$toast.error('ກະລຸນາເລືອກໄຟລ໌ກ່ອນ')
                return
            }

            if (!this.form.id && this.isCreate) {
                this.$toast.error('ກະລຸນາບັນທຶກຂໍ້ມູນບໍລິສັດກ່ອນອັບໂຫລດຮູບ')
                return
            }

            this.uploading = true

            try {
                const formData = new FormData()
                formData.append('profile_image', this.selectedFile)

                const companyId = this.form.id || this.recordId
                const response = await this.$axios.post(
                    `api/company/upload-profile-image/${companyId}`,
                    formData,
                    {
                        headers: {
                            'Content-Type': 'multipart/form-data'
                        }
                    }
                )

                // Update form with new image path
                this.form.profile_image_path = response.data.profile_image_path

                this.$toast.success('ອັບໂຫລດຮູບສຳເລັດແລ້ວ')
                this.clearSelectedFile()
                this.refreshData()

            } catch (error) {
                console.error('Upload error:', error)
                const errorMessage = error.response?.data?.message || 'ອັບໂຫລດຮູບບໍ່ສຳເລັດ'
                this.$toast.error(errorMessage)
            } finally {
                this.uploading = false
            }
        },

        async deleteProfileImage() {
            if (!this.form.profile_image_path) return

            try {
                const result = await this.$swal.fire({
                    title: 'ຢືນຢັນການລຶບ',
                    text: 'ທ່ານຕ້ອງການລຶບຮູບໂປຣໄຟລ໌ນີ້ແທ້ບໍ?',
                    icon: 'warning',
                    showCancelButton: true,
                    confirmButtonColor: '#d33',
                    cancelButtonColor: '#3085d6',
                    confirmButtonText: 'ລຶບ',
                    cancelButtonText: 'ຍົກເລີກ'
                })

                if (result.isConfirmed) {
                    this.deleting = true

                    const companyId = this.form.id || this.recordId
                    await this.$axios.delete(`api/company/delete-profile-image/${companyId}`)

                    // Clear image path from form
                    this.form.profile_image_path = null

                    this.$toast.success('ລຶບຮູບສຳເລັດແລ້ວ')
                    this.refreshData()
                }
            } catch (error) {
                console.error('Delete error:', error)
                const errorMessage = error.response?.data?.message || 'ລຶບຮູບບໍ່ສຳເລັດ'
                this.$toast.error(errorMessage)
            } finally {
                this.deleting = false
            }
        },

        refreshData() {
            this.$emit('reload-data')
        }
    }
};
